namespace ResearchAgent;

/// <summary>
/// Simple in-memory notepad for the research agent to store findings.
/// </summary>
public sealed class Notepad
{
    private readonly List<string> _notes = [];

    public void Add(string note)
    {
        _notes.Add(note);
    }

    public IReadOnlyList<string> GetAll() => _notes.AsReadOnly();
}

using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;

namespace ResearchAgent;

/// <summary>
/// Tools available to the research agent for web searching and note-taking.
/// </summary>
public sealed class ResearchTools(Notepad notepad)
{
    private static readonly HttpClient s_httpClient = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
    };

    /// <summary>
    /// Searches the web for information on a given query and returns relevant results.
    /// </summary>
    /// <param name="query">The search query to look up on the web.</param>
    /// <returns>A string containing search results with titles, snippets, and URLs.</returns>
    [Description("Searches the web for information on a given query and returns relevant results.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up on the web")] string query)
    {
        try
        {
            // Use DuckDuckGo Instant Answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

            var response = await s_httpClient.GetFromJsonAsync<JsonElement>(url);

            var results = new List<string>();

            // Extract abstract if available
            if (response.TryGetProperty("Abstract", out var abstract_) &&
                abstract_.GetString() is { Length: > 0 } abstractText)
            {
                var source = response.TryGetProperty("AbstractSource", out var src)
                    ? src.GetString() : "Unknown";
                results.Add($"[{source}] {abstractText}");
            }

            // Extract related topics
            if (response.TryGetProperty("RelatedTopics", out var topics) &&
                topics.ValueKind == JsonValueKind.Array)
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text) &&
                        text.GetString() is { Length: > 0 } topicText)
                    {
                        var topicUrl = topic.TryGetProperty("FirstURL", out var u)
                            ? u.GetString() : "";
                        results.Add($"- {topicText} ({topicUrl})");
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"No detailed results found for '{query}'. Try rephrasing the query.";
            }

            return string.Join("\n\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    /// <summary>
    /// Saves a research note for later reference.
    /// </summary>
    /// <param name="note">The note content to save.</param>
    /// <returns>Confirmation that the note was saved.</returns>
    [Description("Saves a research note for later reference. Use this to record important findings.")]
    public string SaveNote(
        [Description("The note content to save")] string note)
    {
        notepad.Add(note);
        return $"Note saved (total notes: {notepad.GetAll().Count}).";
    }

    /// <summary>
    /// Retrieves all saved research notes.
    /// </summary>
    /// <returns>All notes saved so far, numbered.</returns>
    [Description("Retrieves all saved research notes to review findings before summarizing.")]
    public string GetNotes()
    {
        var notes = notepad.GetAll();
        if (notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        return string.Join("\n", notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

